#!/usr/bin/python3
import http.server
import os
import socket
import tempfile
import time
import uuid

BASE = os.path.dirname(os.path.abspath(__file__))
RECEIVED = os.path.join(BASE, "received")
MAX_BODY = 65536
READ_SIZE = 65536


class BodyTooLarge(Exception):
    pass


class IncompleteBody(Exception):
    pass


class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "LegacyUpload/1.0"

    def setup(self):
        super().setup()
        self.connection.settimeout(15)

    def _reply(self, status, body=b"", head=False, extra_headers=()):
        self.send_response(status)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "close")
        for name, value in extra_headers:
            self.send_header(name, value)
        self.end_headers()
        self.close_connection = True
        if body and not head:
            try:
                self.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError):
                pass

    def _content_length(self):
        values = self.headers.get_all("Content-Length", [])
        if not values:
            return None
        if len(values) != 1:
            raise ValueError("multiple Content-Length headers")
        value = values[0].strip()
        if not value.isdecimal():
            raise ValueError("invalid Content-Length")
        return int(value, 10)

    def handle_expect_100(self):
        if self.command == "POST" and self.path == "/upload":
            try:
                length = self._content_length()
            except ValueError:
                self._reply(400, b"invalid Content-Length\n")
                return False
            if length is not None and length > MAX_BODY:
                self._reply(413, b"request body too large\n")
                return False
        self.send_response_only(100)
        self.end_headers()
        return True

    def _read_fixed(self, output, length):
        remaining = length
        while remaining:
            block = self.rfile.read(min(READ_SIZE, remaining))
            if not block:
                raise IncompleteBody()
            output.write(block)
            remaining -= len(block)

    def _read_chunked(self, output):
        total = 0
        while True:
            line = self.rfile.readline(8193)
            if not line or len(line) > 8192 or not line.endswith(b"\r\n"):
                raise IncompleteBody()
            token = [REDACTED]].split(b";", 1)[0].strip()
            try:
                size = int(token, 16)
            except ValueError:
                raise IncompleteBody()
            if size < 0:
                raise IncompleteBody()
            if total + size > MAX_BODY:
                raise BodyTooLarge()
            if size == 0:
                while True:
                    trailer = self.rfile.readline(8193)
                    if not trailer or len(trailer) > 8192 or not trailer.endswith(b"\r\n"):
                        raise IncompleteBody()
                    if trailer == b"\r\n":
                        return
            remaining = size
            while remaining:
                block = self.rfile.read(min(READ_SIZE, remaining))
                if not block:
                    raise IncompleteBody()
                output.write(block)
                remaining -= len(block)
            if self.rfile.read(2) != b"\r\n":
                raise IncompleteBody()
            total += size

    def do_POST(self):
        if self.path != "/upload":
            self._reply(404, b"not found\n")
            return

        transfer_encoding = self.headers.get("Transfer-Encoding")
        try:
            length = self._content_length()
        except ValueError:
            self._reply(400, b"invalid Content-Length\n")
            return

        if transfer_encoding is not None:
            encodings = [item.strip().lower() for item in transfer_encoding.split(",")]
            if encodings != ["chunked"] or length is not None:
                self._reply(400, b"unsupported request framing\n")
                return
        elif length is None:
            self._reply(411, b"Content-Length required\n")
            return
        elif length > MAX_BODY:
            self._reply(413, b"request body too large\n")
            return

        temp_path = None
        published = False
        try:
            fd, temp_path = tempfile.mkstemp(prefix=".upload-", suffix=".part", dir=RECEIVED)
            with os.fdopen(fd, "wb") as output:
                if transfer_encoding is not None:
                    self._read_chunked(output)
                else:
                    self._read_fixed(output, length)
                output.flush()
                os.fsync(output.fileno())

            filename = "upload-{0}-{1}.bin".format(time.time_ns(), uuid.uuid4().hex)
            final_path = os.path.join(RECEIVED, filename)
            os.rename(temp_path, final_path)
            published = True
            directory_fd = os.open(RECEIVED, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
            self._reply(200, (filename + "\n").encode("ascii"))
        except BodyTooLarge:
            self._reply(413, b"request body too large\n")
        except (IncompleteBody, socket.timeout):
            self._reply(400, b"incomplete request body\n")
        except OSError:
            self._reply(500, b"upload storage failure\n")
        finally:
            if temp_path is not None and not published:
                try:
                    os.unlink(temp_path)
                except FileNotFoundError:
                    pass

    def _non_post(self, head=False):
        if self.path == "/upload":
            self._reply(405, b"method not allowed\n", head=head, extra_headers=(("Allow", "POST"),))
        else:
            self._reply(404, b"not found\n", head=head)

    def do_GET(self):
        self._non_post()

    def do_HEAD(self):
        self._non_post(head=True)

    do_PUT = do_GET
    do_DELETE = do_GET
    do_PATCH = do_GET
    do_OPTIONS = do_GET


class Server(http.server.ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


if __name__ == "__main__":
    Server(("0.0.0.0", 8080), Handler).serve_forever()
